with unpacked as (select id, customer_id, created_at, ship_to, exists(items, x -> x.price > 100) as has_premium_item, array_max(transform(items, x -> x.price)) as max_item_price, forall(items, x -> x.qty <= 5) as all_small_qty, attributes['utm_source'] as utm_source, ship_to.zip as ship_zip from carts) select date_trunc('hour', created_at) as hour_window, avg(max_item_price) as avg_max_item_price, avg(max_item_price) as avg_max_item_price_2, min(created_at) as started_at, count(distinct id) as distinct_ids, count(*) as row_count, min(created_at) as first_created_at from unpacked group by hour_window order by avg_max_item_price_2 desc nulls first;
